Inheritance (Reusing Code)
Inheritance allows a class (child) to inherit attributes and methods from another
class (parent). Example of Single Inheritance
class BankAccount:
def __init__(self, balance):
self.__balance = balance  # Private Attribute
def get_balance(self):
# Getter
return self.__balance
def deposit(self, amount):
# Setter
if amount > 0:
self.__balance += amount
# Using Encapsulation
account = BankAccount(1000)
account.deposit(500)
print(account.get_balance())
# Output: 1500
class Animal:
def speak(self):
return "Animal makes a sound"
class Dog(Animal):
# Inheriting from Animal
def speak(self):
return "Bark"
dog = Dog()
print(dog.speak())
# Output: Bark

Polymorphism (Same Method, Different Behavior)
Polymorphism allows different classes to use the same method name. Method Overriding Example
class A:
def method_a(self):
return "Method A"
class B:
def method_b(self):
return "Method B"
class C(A, B):
# Multiple Inheritance
pass
obj = C()
print(obj.method_a())
# Output: Method A
print(obj.method_b())
# Output: Method B
class Bird:
def fly(self):
return "Birds can fly"

It is achieved using abstract base classes ( ABC module). class Penguin(Bird):
def fly(self):
return "Penguins cannot fly"
bird = Bird()
penguin = Penguin()
print(bird.fly())
# Output: Birds can fly
print(penguin.fly())
# Output: Penguins cannot fly
from abc import ABC, abstractmethod
class Shape(ABC):
@abstractmethod
def area(self):
pass
# No implementation
class Square(Shape):
def __init__(self, side):
self.side = side
def area(self):
return self.side * self.side  # Implemented in child clas
square = Square(4)
print(square.area())
# Output: 16

